importScripts('typescript.js');
async function assess(code,m,libs){
 const filename='/assessment.ts';const source=code+'\n'+m.contract;const options={strict:true,noEmit:true,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.CommonJS,lib:['lib.es2020.d.ts']};const files={[filename]:source,...libs};const host={getSourceFile:(name,lang)=>files[name]===undefined?undefined:ts.createSourceFile(name,files[name],lang,true),getDefaultLibFileName:()=>'/lib.es2020.d.ts',writeFile:()=>{},getCurrentDirectory:()=> '/',getDirectories:()=>[],fileExists:n=>files[n]!==undefined,readFile:n=>files[n],getCanonicalFileName:n=>n,useCaseSensitiveFileNames:()=>true,getNewLine:()=> '\n'};
 const program=ts.createProgram([filename],options,host);const diagnostics=ts.getPreEmitDiagnostics(program).map(d=>{const location=d.file&&d.start!==undefined?d.file.getLineAndCharacterOfPosition(d.start):null;return (location?`Line ${location.line+1}:${location.character+1} — `:'')+ts.flattenDiagnosticMessageText(d.messageText,'\n');});
 if(/@ts-(ignore|nocheck|expect-error)/.test(code))diagnostics.push('Remove TypeScript suppression comments from your answer.');const ast=ts.createSourceFile(filename,code,ts.ScriptTarget.ES2020,true);function visit(n){if(n.kind===ts.SyntaxKind.AnyKeyword)diagnostics.push('Use a precise type or unknown instead of any in this exercise.');ts.forEachChild(n,visit);}visit(ast);
 if(m.title.startsWith('Modules')){for(const name of ['User','canViewCase'])if(!ast.statements.some(n=>n.name?.text===name&&n.modifiers?.some(x=>x.kind===ts.SyntaxKind.ExportKeyword)))diagnostics.push(`Export ${name} so other modules can use it.`);}
 const js=ts.transpileModule(code,{compilerOptions:{target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.CommonJS}}).outputText;const AsyncFunction=Object.getPrototypeOf(async function(){}).constructor;const results=[];for(const [name,test] of m.tests){try{const fn=new AsyncFunction('exports',js+'\nreturn Boolean('+test+');');results.push({name,ok:await fn({})});}catch(e){results.push({name,ok:false,error:String(e.message||e)});}}
 return {diagnostics:[...new Set(diagnostics)],results};
}
async function loadLibs(){const libs={};async function load(name){const path='/'+name;if(path in libs)return;libs[path]='';const response=await fetch('lib/'+name);if(!response.ok)throw Error('TypeScript libraries could not load.');const text=await response.text();libs[path]=text;await Promise.all([...text.matchAll(/<reference lib="([^"]+)"/g)].map(m=>load('lib.'+m[1]+'.d.ts')));}await load('lib.es2020.d.ts');return libs;}
if(typeof self!=='undefined')self.onmessage=async({data})=>{try{self.postMessage(await assess(data.code,data.module,await loadLibs()));}catch(e){self.postMessage({error:String(e.message||e)});}};
